Here’s a minimal **web app** that tracks approximate location **without asking for browser/OS location permission**. It uses the visitor’s IP address, so it works without `navigator.geolocation` and without Android/iOS location permissions.

> ⚠️ Legal note: “No permission prompt” does **not** mean “no consent required.” IP addresses and location data are personal data under GDPR/CCPA/etc. You still need a lawful basis, privacy notice, and often consent. This is a technical demo, not legal advice.

## How it works

- Browser calls your server.
- Server reads the client IP.
- Server geolocates the IP using `geoip-lite` or a fallback API.
- Server logs approximate city/country/lat-lon.
- No GPS, no location permission dialog.

## Setup

```bash
mkdir ip-tracker
cd ip-tracker
npm init -y
npm i express request-ip geoip-lite
mkdir public
```

## `server.js`

```js
const express = require('express');
const requestIp = require('request-ip');
const geoip = require('geoip-lite');
const fs = require('fs');
const path = require('path');

const app = express();
app.set('trust proxy', true);
app.use(express.static('public'));
app.use(express.json());

const LOG = path.join(__dirname, 'locations.jsonl');

async function geolocate(ip) {
  // Local GeoIP database
  const local = geoip.lookup(ip);
  if (local) {
    return {
      source: 'geoip-lite',
      country: local.country,
      region: local.region,
      city: local.city,
      ll: local.ll,
      timezone: local.timezone
    };
  }

  // Fallback for localhost / unknown IPs
  try {
    const r = await fetch(`https://ipapi.co/${ip}/json/`);
    const j = await r.json();
    if (j.error) return null;

    return {
      source: 'ipapi.co',
      country: j.country_code,
      region: j.region_code,
      city: j.city,
      ll: [j.latitude, j.longitude],
      timezone: j.timezone
    };
  } catch {
    return null;
  }
}

app.post('/track', async (req, res) => {
  const ip = (requestIp.getClientIp(req) || req.ip || '').replace('::ffff:', '');
  const geo = await geolocate(ip);

  const record = {
    ts: new Date().toISOString(),
    ip,
    userAgent: req.headers['user-agent'],
    language: req.headers['accept-language'],
    referer: req.headers.referer,
    page: req.body?.page,
    geo
  };

  fs.appendFileSync(LOG, JSON.stringify(record) + '\n');
  console.log(record);

  res.json({ ok: true, geo });
});

app.get('/locations', (req, res) => {
  const lines = fs.existsSync(LOG)
    ? fs.readFileSync(LOG, 'utf8').trim().split('\n').filter(Boolean)
    : [];

  res.json(lines.map(JSON.parse));
});

app.listen(3000, () => {
  console.log('Tracker running at http://localhost:3000');
});
```

