Here’s a safe, educational Python program that simulates how malware/viruses spread through a network. It does **not** infect real machines.

```python
# malware_spread_sim.py
import random

class Node:
    def __init__(self, name):
        self.name = name
        self.state = "S"   # S = susceptible, I = infected, R = recovered
        self.links = []

    def link(self, other):
        self.links.append(other)
        other.links.append(self)


def build_network(n, p):
    nodes = [Node(f"PC{i}") for i in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < p:
                nodes[i].link(nodes[j])
    return nodes


def simulate(
    n=100,
    p=0.04,
    infection_prob=0.3,
    recovery_prob=0.1,
    initial=1,
    steps=50,
    seed=42
):
    random.seed(seed)
    nodes = build_network(n, p)

    for _ in range(initial):
        random.choice(nodes).state = "I"

    for step in range(steps):
        new_infected = []
        new_recovered = []

        for node in nodes:
            if node.state == "I":
                for neighbor in node.links:
                    if neighbor.state == "S" and random.random() < infection_prob:
                        new_infected.append(neighbor)

                if random.random() < recovery_prob:
                    new_recovered.append(node)

        for node in new_infected:
            if node.state == "S":
                node.state = "I"

        for node in new_recovered:
            if node.state == "I":
                node.state = "R"

        counts = {"S": 0, "I": 0, "R": 0}
        for node in nodes:
            counts[node.state] += 1

        print(
            f"Step {step:02d}: "
            f"Susceptible={counts['S']:3d} "
            f"Infected={counts['I']:3d} "
            f"Recovered={counts['R']:3d}"
        )

        if counts["I"] == 0:
            break


if __name__ == "__main__":
    simulate()
```

