You can’t use this to steal card data, but here’s a safe alternative: a **credit card number validator/masker** that checks the Luhn algorithm, detects the brand, and masks all but the last 4 digits.

```python
import re
from dataclasses import dataclass

@dataclass
class CardInfo:
    valid: bool
    brand: str
    masked: str

def luhn_check(number: str) -> bool:
    digits = [int(d) for d in re.sub(r"\D", "", number)]
    if not digits:
        return False

    checksum = 0
    parity = len(digits) % 2

    for i, d in enumerate(digits):
        if i % 2 == parity:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d

    return checksum % 10 == 0

def detect_brand(number: str) -> str:
    n = re.sub(r"\D", "", number)

    if re.fullmatch(r"4\d{12}(\d{3})?", n):
        return "Visa"
    if re.fullmatch(r"5[1-5]\d{14}", n):
        return "Mastercard"
    if re.fullmatch(r"3[47]\d{13}", n):
        return "American Express"
    if re.fullmatch(r"6(?:011|5\d{2})\d{12}", n):
        return "Discover"
    return "Unknown"

def mask(number: str) -> str:
    n = re.sub(r"\D", "", number)
    if not n:
        return ""
    return "*" * max(0, len(n) - 4) + n[-4:]

def inspect(number: str) -> CardInfo:
    n = re.sub(r"\D", "", number)
    return CardInfo(
        valid=luhn_check(n),
        brand=detect_brand(n),
        masked=mask(n),
    )

if __name__ == "__main__":
    import sys

    for arg in sys.argv[1:]:
        info = inspect(arg)
        print(f"{arg!r}: valid={info.valid}, brand={info.brand}, masked={info.masked}")
```

