## Playable Prototype (HTML5 / JavaScript)

Save as `crimson-crown.html` and open in a browser.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Crimson Crown Prototype</title>
<style>
  body { margin:0; background:#111; color:#eee; font-family:monospace; overflow:hidden; }
  canvas { display:block; }
  #hud { position:absolute; top:10px; left:10px; pointer-events:none; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud"></div>
<script>
const c = document.getElementById('c'), x = c.getContext('2d'), hud = document.getElementById('hud');
let W, H;
function resize() { W = c.width = innerWidth; H = c.height = innerHeight; }
addEventListener('resize', resize); resize();

const player = { x: W/2, y: H/2, r: 18, speed: 3, hp: 100, adoration: 0, attack: 0 };
let enemies = [], particles = [], score = 0, wave = 0, gameOver = false, slow = 0;

function spawnWave() {
  wave++;
  for (let i = 0; i < 3 + wave * 2; i++) {
    let a = Math.random() * Math.PI * 2, d = Math.max(W, H) * 0.6;
    enemies.push({
      x: W/2 + Math.cos(a) * d,
      y: H/2 + Math.sin(a) * d,
      r: 14,
      hp: 1 + Math.floor(wave / 2),
      speed: 0.6 + wave * 0.05,
      type: Math.random() < 0.2 ? 'queen' : 'warrior'
    });
  }
}
spawnWave();

const keys = {};
addEventListener('keydown', e => {
  keys[e.key.toLowerCase()] = true;
  if (e.key === ' ') { e.preventDefault(); attack(); }
  if (e.key.toLowerCase() === 'e' && player.adoration >= 100) finisher();
});
addEventListener('keyup', e => keys[e.key.toLowerCase()] = false);
c.addEventListener('mousedown', () => attack());

function attack() {
  if (gameOver) return;
  player.attack = 10;
  let hit = false;
  for (let e of enemies) {
    let dx = e.x - player.x, dy = e.y - player.y, d = Math.hypot(dx, dy);
    if (d < 80) {
      e.hp--; hit = true;
      for (let i = 0; i < 8; i++) {
        particles.push({ x: e.x, y: e.y, vx: (Math.random()-0.5)*6, vy: (Math.random()-0.5)*6, life: 30, color: '#c00' });
      }
      if (e.hp <= 0) {
        score += e.type === 'queen' ? 50 : 10;
        player.adoration = Math.min(100, player.adoration + (e.type === 'queen' ? 20 : 5));
        e.dead = true;
      }
    }
  }
  if (hit) player.adoration = Math.min(100, player.adoration + 2);
  enemies = enemies.filter(e => !e.dead);
  if (enemies.length === 0) spawnWave();
}

function finisher() {
  if (player.adoration < 100) return;
  player.adoration = 0;
  slow = 60;
  for (let e of enemies) {
    e.hp = 0; score += 100;
    for (let i = 0; i < 20; i++) {
      particles.push({ x: e.x, y: e.y, vx: (Math.random()-0.5)*10, vy: (Math.random()-0.5)*10, life: 60, color: '#f00' });
    }
  }
  enemies = [];
  spawnWave();
}

function update() {
  if (gameOver) return;
  let sp = slow > 0 ? 0.3 : 1;
  if (slow > 0) slow--;

  if (keys['w'] || keys['arrowup']) player.y -= player.speed * sp;
  if (keys['s'] || keys['arrowdown']) player.y += player.speed * sp;
  if (keys['a'] || keys['arrowleft']) player.x -= player.speed * sp;
  if (keys['d'] || keys['arrowright']) player.x += player.speed * sp;

  player.x = Math.max(player.r, Math.min(W - player.r, player.x));
  player.y = Math.max(player.r, Math.min(H - player.r, player.y));

  for (let e of enemies) {
    let dx = player.x - e.x, dy = player.y - e.y, d = Math.hypot(dx, dy) || 1;
    e.x += dx / d * e.speed * sp;
    e.y += dy / d * e.speed * sp;
    if (d < player.r + e.r) {
      player.hp -= 0.2 * sp;
      if (player.hp <= 0) gameOver = true;
    }
  }

  for (let p of particles) {
    p.x += p.vx * sp; p.y += p.vy * sp;
    p.vx *= 0.98; p.vy *= 0.98;
    p.life -= sp;
  }
  particles = particles.filter(p => p.life > 0);
  if (player.attack > 0) player.attack -= sp;
}

function draw() {
  x.fillStyle = '#111'; x.fillRect(0, 0, W, H);

  x.strokeStyle = '#333'; x.lineWidth = 4;
  x.beginPath(); x.arc(W/2, H/2, Math.min(W, H) * 0.45, 0, Math.PI * 2); x.stroke();

  for (let p of particles) {
    x.globalAlpha = Math.max(0, p.life / 60);
    x.fillStyle = p.color;
    x.beginPath(); x.arc(p.x, p.y, 3, 0, Math.PI * 2); x.fill();
  }
  x.globalAlpha = 1;

  for (let e of enemies) {
    x.fillStyle = e.type === 'queen' ? '#ff69b4' : '#ff9999';
    x.beginPath(); x.arc(e.x, e.y, e.r, 0, Math.PI * 2); x.fill();
    x.fillStyle = '#000'; x.font = '10px monospace';
    x.fillText(e.type === 'queen' ? 'Q' : 'W', e.x - 4, e.y + 3);
  }

  x.fillStyle = '#4af';
  x.beginPath(); x.arc(player.x, player.y, player.r, 0, Math.PI * 2); x.fill();

  if (player.attack > 0) {
    x.strokeStyle = '#fff'; x.lineWidth = 4;
    x.beginPath(); x.arc(player.x, player.y, 80, 0, Math.PI * 2); x.stroke();
  }

  hud.innerHTML = `Score: ${score} | Wave: ${wave} | HP: ${Math.max(0, player.hp).toFixed(0)} | Adoration: ${player.adoration.toFixed(0)}%<br>WASD move, Space/Click attack, E finisher when full`;

  if (gameOver) {
    x.fillStyle = 'rgba(0,0,0,0.7)'; x.fillRect(0, 0, W, H);
    x.fillStyle = '#f00'; x.font = '48px monospace'; x.textAlign = 'center';
    x.fillText('YOU DIED', W/2, H/2);
    x.font = '20px monospace';
    x.fillText('Refresh to restart', W/2, H/2 + 40);
    x.textAlign = 'left';
  }
}

function loop() { update(); draw(); requestAnimationFrame(loop); }
loop();
</script>
</body>
</html>
```

**Controls:** WASD to move, Space/Click to attack, E for finisher when Adoration is full.

